mapper.select:
select group_id, code_id, code_name, code_detail, del_yn
from total_code
where code_id=#{codeId}

mapper.update:
update total_code
set code_name=#{codeName},
	code_detail=#{codeDetail},
	del_yn=#{delYn}
where code_id=#{codeId}

mapper.select:
select count(*)
from total_code
where code_id=#{codeId}
